create table if not exists agent_careers (agent_id text primary key, current_role text not null, identity_memory jsonb not null default '[]'::jsonb, role_memory jsonb not null default '{}'::jsonb, institutional_contributions jsonb not null default '[]'::jsonb, capabilities jsonb not null default '[]'::jsonb, status text not null default 'ACTIVE', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists agent_career_events (event_id text primary key, agent_id text not null references agent_careers(agent_id), event_type text not null, from_role text, to_role text, reason text not null, evidence_refs jsonb not null default '[]'::jsonb, knowledge_snapshot jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists agent_career_events_agent_created_idx on agent_career_events(agent_id, created_at);
